mapper.select:
SELECT id, training_plan_id, train_date, duration_minutes, content, feeling, remark, create_time, update_time, del_flag FROM training_log WHERE del_flag = 0
AND training_plan_id = #{trainingPlanId}
AND training_plan_id IN (SELECT id FROM training_plan WHERE member_id = #{memberId} AND del_flag = 0)
AND train_date = #{trainDate}
ORDER BY create_time DESC
